function canBePalindrome(text) {
  const isPalindrome = (i, j) => {
    while (i < j) {
      if (text[i] !== text[j]) return false
      i++; j--
    }
    return true
  }
  let i = 0
  let j = text.length - 1
  while (i < j) {
    if (text[i] !== text[j]) return isPalindrome(i + 1, j) || isPalindrome(i, j - 1)
    i++; j--
  }
  return true
}

