def can_be_palindrome(text):
    def is_palindrome(i, j):
        while i < j:
            if text[i] != text[j]:
                return False
            i += 1
            j -= 1
        return True

    i, j = 0, len(text) - 1
    while i < j:
        if text[i] != text[j]:
            return is_palindrome(i + 1, j) or is_palindrome(i, j - 1)
        i += 1
        j -= 1
    return True
